class QueueStack:
    def __init__(self):
        self.queue = deque()

    def push(self, x):
        self.queue.append(x)
        for _ in range(len(self.queue) - 1):
            self.queue.append(self.queue.popleft())

    def pop(self):
        return self.queue.popleft() if self.queue else -1

    def top(self):
        return self.queue[0] if self.queue else -1

    def isEmpty(self):
        return not self.queue

    def size(self):
        return len(self.queue)

