        if self.tail is None:
            self.head = self.tail = node
        else:
            self.tail.next = node
            self.tail = node
        self.count += 1

    def pop(self):
        if self.head is None:
            return -1
        value = self.head.val
        self.head = self.head.next
        if self.head is None:
            self.tail = None
        self.count -= 1
        return value

    def peek(self):
        return -1 if self.head is None else self.head.val

    def isEmpty(self):
        return self.head is None

    def size(self):
        return self.count

